async function start(){if(state.mode==='live'){
 if(!window.supabase){toast('Supabase SDK failed to load. Check your internet.',true);state.mode='demo';}
 else{state.sb=window.supabase.createClient(config.url,config.key);const {data:{session}}=await state.sb.auth.getSession();state.me=session?.user||null;
 state.sb.auth.onAuthStateChange(async(_ev,session)=>{const next=session?.user||null;if(next?.id!==state.me?.id){state.me=next;await refresh();app()}});
 if(state.me)await refresh();}}
 if(state.mode==='demo')loadPreview();app();if(state.mode==='live'){setInterval(async()=>{if(!state.me||state.modal||document.activeElement?.tagName==='INPUT'||document.activeElement?.tagName==='TEXTAREA')return;await refresh();if(state.profile?.verified&&!state.profile.must_change_password)renderShell()},45000)}}
function loadPreview(){const demoId=sessionStorage.getItem('crh_demo_user')||'demo-self';state.me={id:demoId};state.profile={id:demoId,name:demoId==='demo-self'?'Demo Student':'Demonstration Owner',roll:demoId==='demo-self'?'DEMO001':'DEMO002',department:'ECE',academic_year:'1',section:'C',residence:'Day Scholar',role:'student',verified:true,must_change_password:false};for(const k of Object.keys(preview))state[k]=['notifications','wishlist'].includes(k)?preview[k].filter(x=>x.user_id===demoId):preview[k];state.students=[{id:'demo-self',name:'Demo Student',department:'ECE'},{id:'demo-other',name:'Demonstration Owner',department:'ECE'}]}
async function refresh(){if(state.mode==='demo'){loadPreview();return}if(!state.me)return;
 try{let {data:p,error:pe}=await state.sb.from('profiles').select('*').eq('id',state.me.id).single();if(pe)throw pe;state.profile=p;
 if(!p.verified)return;
 const tables=['resources','requests','notifications','wishlists','messages','posts','announcements','reviews','reports','profiles'];
 const results=await Promise.all(tables.map(t=>state.sb.from(t).select('*').order('created_at',{ascending:false}).limit(t==='messages'?200:300)));
 for(let i=0;i<tables.length;i++){if(results[i].error){console.warn(tables[i],results[i].error.message);continue}state[tables[i]==='profiles'?'students':tables[i]==='wishlists'?'wishlist':tables[i]]=results[i].data||[]}
 }catch(e){toast('Loading failed: '+e.message,true)} }
