function enableGlassMotion(){
  const nodes=document.querySelectorAll('.landing-shell .reveal');
  if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){nodes.forEach(x=>x.classList.add('in-view'));return;}
  const observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}},{threshold:.08,rootMargin:'0px 0px 50px 0px'});
  nodes.forEach(x=>observer.observe(x));
}
